package notification.core.recipient;/** * Represents a notification recipient. * * This abstraction is channel-independent. * Email, SMS, WhatsApp, Push, etc. can have their own * recipient implementations. */public interface Recipient {    /**     * Unique identifier of the recipient.     *     * @return recipient ID     */    String id();    /**     * Preferred language of the recipient.     *     * @return language code, for example "en", "fr", "hi"     */    String language();}